{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Tocotrienol, a lipophilic chromanol with an unsaturated isoprenoid side chain, has poor oral bioavailability in humans; this is the most structurally relevant low-F evidence for the query's polar cyclic head plus long isoprenoid tail.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Lycopene, a large lipophilic isoprenoid, showed only about 1.2% systemic availability in a human study, and multiple other lycopene records report similarly low values, reinforcing that large polyisoprenoid lipids are often poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Phytoene, the closest-scoring analogue, was estimated to be 58.5% bioavailable in humans, which would support high F; however, it lacks the quinone head and its high estimate comes from compartmental modeling, limiting transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Hyperforin, a prenylated phloroglucinol, showed high oral bioavailability in humans, but its smaller size and administration as an extract reduce transferability to the much larger ubiquinone query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a large, highly lipophilic ubiquinone (CoQ8) with a polar quinone head and an eight-unit isoprenoid tail. The most structurally relevant experimental evidence—tocotrienol poor bioavailability and lycopene very low systemic availability—supports F <20%. The closest-scoring phytoene high-bioavailability result is contradicted by its lack of a quinone and different bioaccessibility; overall low is better supported, but with substantial uncertainty.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability data for ubiquinone-8 or CoQ10 in the evidence set.",
    "Phytoene high estimate is from compartmental modeling rather than a true absolute F measurement.",
    "Tocotrienol 'poor' is not quantified relative to the 20% threshold.",
    "Formulation and food-matrix effects differ across evidence records and are not controlled for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

